{
  "pdf_page": 506,
  "book_page": 476,
  "verified_by": "claude-opus-5.5",
  "verified_on": "2026-10-14",
  "entries": [
    {
      "entry": 0,
      "root": "Ters",
      "verdict": "confirmed",
